namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly string[] _templates =
    [
        "Deployment to production completed successfully.",
        "New pull request #{{id}} opened by teammate.",
        "Build pipeline failed — check logs.",
        "Your subscription renews in 3 days.",
        "Server CPU usage exceeded 90%.",
        "Database backup finished.",
        "New comment on issue #{{id}}.",
        "Security patch available for dependency.",
    ];

    /// <summary>Returns a batch of seed notifications (called once during prerender).</summary>
    public Task<List<Notification>> GetInitialNotificationsAsync()
    {
        var now = DateTime.UtcNow;
        var items = new List<Notification>();
        for (var i = 0; i < 5; i++)
        {
            items.Add(new Notification(
                _nextId,
                _templates[_nextId % _templates.Length].Replace("{{id}}", _nextId.ToString()),
                now.AddMinutes(-5 * (5 - i))));
            _nextId++;
        }
        return Task.FromResult(items);
    }

    /// <summary>Simulates checking for new notifications since the last known id.</summary>
    public Task<List<Notification>> CheckForNewAsync(int lastKnownId)
    {
        var result = new List<Notification>();

        // ~40% chance a new notification arrives each poll
        if (Random.Shared.Next(100) < 40)
        {
            var id = lastKnownId + 1;
            result.Add(new Notification(
                id,
                _templates[id % _templates.Length].Replace("{{id}}", id.ToString()),
                DateTime.UtcNow));
        }

        return Task.FromResult(result);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorNotifications.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted ms-3 text-nowrap">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (PersistedNotifications is not null)
        {
            // Restored from prerender — skip the service call
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationSvc.GetInitialNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var lastId = notifications.Count > 0
                    ? notifications.Max(n => n.Id)
                    : 0;

                var newer = await NotificationSvc.CheckForNewAsync(lastId);
                if (newer.Count > 0)
                {
                    notifications.AddRange(newer);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

